-- Reading Club 10+ · урок 3: курс, юнит, план (kind=lesson) и ДЗ (kind=homework). Черновики.
do $$
declare v_course uuid; v_unit uuid; v_plan uuid; v_hw uuid;
begin
  select id into v_course from classroom_courses where slug = 'reading10';
  if v_course is null then
    insert into classroom_courses (slug, title, description, sort_order)
    values ('reading10', 'Reading Club 10+', 'Курс чтения (фоника) для 10–12 лет · 10 уроков', 10) returning id into v_course;
  end if;
  select id into v_unit from classroom_units where course_id = v_course and sort_order = 1;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order) values (v_course, 'Module 1 · Code', 1) returning id into v_unit;
  end if;
  select id into v_plan from classroom_lessons where unit_id = v_unit and sort_order = 2 and kind = 'lesson';
  if v_plan is null then
    insert into classroom_lessons (unit_id, title, kind, sort_order, is_published) values (v_unit, 'Lesson 3 · The Red Cup', 'lesson', 2, false) returning id into v_plan;
  end if;
  select id into v_hw from classroom_lessons where unit_id = v_unit and sort_order = 12 and kind = 'homework';
  if v_hw is null then
    insert into classroom_lessons (unit_id, title, kind, sort_order, is_published) values (v_unit, 'Homework 3 · The Red Cup', 'homework', 12, false) returning id into v_hw;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
  (v_plan, 'embed', $blk${"url": "https://classroom.wowteach.ru/lessons/reading10/u3.html"}$blk$::jsonb, 0),
  (v_plan, 'text', $blk${"html": "<div style=\"padding:16px 18px;background:#F2FAFE;border-radius:14px;border:2px solid #CFE6F4\"><h3 style=\"margin:0 0 6px;color:#0A5C86\">🔐 Как провести урок</h3><p style=\"margin:0 0 8px\">«Планы уроков» → этот урок → <b>«▶ Показ»</b>: урок откроется на весь экран. Демонстрируйте в Zoom <b>эту вкладку</b>. На экране ученика — только короткие инструкции по-английски: историю, задания и объяснения даёт учитель по этому плану.</p><p style=\"margin:0 0 8px\">Вверху справа выберите <b>30</b> или <b>40</b> минут — в режиме 40 появятся дополнительные экраны (розовые точки внизу). <b>⭐ Extra</b> — игры «If time», если осталось время: Code breaker, What's missing?, Find 5 words. Листать можно стрелками на клавиатуре.</p><p style=\"margin:0\">Ученику к уроку нужны <b>тетрадь и ручка</b> — напомните заранее. Звуки букв играют по нажатию; слова можно произносить самому.</p></div>"}$blk$::jsonb, 1),
  (v_plan, 'text', $blk${"html": "<h3>План урока · Lesson 3 · The Red Cup</h3><div style=\"background:#fff;border:1px solid #CFE6F4;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Пройдено:</b> s a t p i n m d o g · I, the, a. &nbsp; <b>Новое:</b> c k e u r · said, are, you. &nbsp; <b>Длительность:</b> 30 мин (40 — с экранами «+»). &nbsp; <b>История:</b> Агент X прислал сообщение «Run! Get the red cup.»</div><table style=\"width:100%;border-collapse:collapse;font-size:14px\"><tr><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Этап</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Мин</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Цель</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">Ход (индивидуально)</th><th style=\"background:#0A5C86;color:#fff;padding:7px 8px;text-align:left\">В группе</th></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>1 · Mission</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Мотивация.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Экран: сцена и телефон с сообщением символами, часть символов серые. T (рус.): «Агент X прислал сообщение, но часть значков мы ещё не знаем. Сегодня откроем пять новых и прочитаем его в конце урока».</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">—</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>2 · Code check</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Повтор символов и звуков.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">S смотрит на символ, называет букву и звук; нажатие открывает букву и звук. T: «Look. Say the sound.»</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По кругу, по символу.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>3 · Tricky words</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">0,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Повтор слов-исключений.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">I, the, a — S читает, нажатие озвучивает.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Хором.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>4 · Chant</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">0,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Беглость: скороговорка урока 2, строки 3–4.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">«A dog, a pot, a map, a pan — Dig it, Sam! Dig it, Dan!» Кнопки 🐢 Slow / ⚡ Fast подсвечивают слова в ритме.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Хором, потом по строке.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Speed run</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">+3</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Беглость: 18 слов на время.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">S читает вслух, T жмёт Next. Рекорд сохраняется.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Каждый на своё время, не сравниваем.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>5 · Homework</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Ошибки ДЗ.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">T показывает 1–2 слова из «Журнала ДЗ», S читает по звукам и целиком.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">—</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>6–10 · New code ×5</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">4</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Новые звуки c, k, e, u, r — по экрану на букву.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Нажатие на карточку: символ «открывается», появляется буква, звучит звук, слово-якорь (cat, kid, egg, umbrella, red). T: «This is c. Sound /k/.» S повторяет звук 2–3 раза. T объясняет: c и k — один звук; e без «й»; u ближе к «а»; r без раската. Символ добавляется в ключ внизу.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Хором, потом по одному.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>11 · Hear it</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">2</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Фонематический слух.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">«Catch the sound /e/»: 🔊 pen, pin, ten, tan, net, nut — ✔ / ✘. Потом устно: c-a-t, r-e-d, s-u-n.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Отвечают все сразу.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>12 · Write it</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Письмо букв.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Буквы пишутся на экране со стрелками; S пишет каждую 3 раза в тетради.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Все пишут.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>13 · Copy</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Списывание слов.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">cat, red — списать, показать в камеру.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Показывают по очереди.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Copy more</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">+2</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Списывание.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">sun, kid, pen — списать и сверить.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>14 · Blending</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">4</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Слияние звуков.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">S нажимает буквы по одной (звучат звуки), сливает, читает; «✔ I can read it!» показывает картинку. cat, kid, pen, ten, sun, cup, red, run.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По слову на ученика.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Real or fake?</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">+3</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Чтение без угадывания.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">cup, dut, red, kep, sun, mip, ten, gog — прочитать вслух и решить.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По очереди.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>15 · Word building</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">2</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Сборка слова.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Буквы-магниты по картинке: cat, sun, red, kid. Ошибся — нажать на букву в слове.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Собирает один, проверяют все.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>16 · Tricky words</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Новые слова-исключения.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">said, are, you — «читаются не по правилам, запоминаем целиком».</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Хором.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>17 · Read</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Слова-исключения во фразе.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">“You are a cat!” said Sam.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По одному.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>18 · Dictation</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">3</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Письмо на слух.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">🔊 pen, cup, rat, kit — в тетради; Check — картинка и слово.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Все пишут.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>+ Dictation</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">+2</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Письмо фразы.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">a red cup.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"></td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>19 · Phrases</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Чтение фраз.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">a red cup · a pet rat · Sam and Dan.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По одной фразе.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>20 · Decode</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Расшифровка.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Сообщение символами: S называет буквы по ключу, нажатие открывает букву. «Run! Get the red cup.»</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По символу по кругу.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>21 · Story</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">1,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Чтение текста.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">История из четырёх строк. T рассказывает по-русски, что было до: ребята расшифровали сообщение и бегут в столовую.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">По строке.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>22 · True or false?</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">0,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Понимание.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">The cup is red. · The cup sits on a pen. · In the cup — a map.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Все отвечают.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>23 · Chant</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">0,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Беглость: скороговорка урока 3, строки 1–2.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">«Run, run, run in the sun! / Get a cup, get a nut!» Slow → Fast. Строки 3–4 — в начале урока 4.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Хором.</td></tr><tr><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\"><b>24 · Mission complete</b></td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">0,5</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Итог.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Счётчик слов, пять новых символов. T: что получилось, монетки, ДЗ.</td><td style=\"border:1px solid #CFE6F4;padding:6px 8px;vertical-align:top\">Каждый говорит, что получилось.</td></tr></table><p style=\"margin-top:10px\"><b>If time (⭐ Extra):</b> Code breaker — слово символами, ввести на время · What's missing? — c_t, s_n, r_d, p_n, k_d · Find 5 words — сетка букв.</p>"}$blk$::jsonb, 2),
  (v_plan, 'text', $blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Homework 3 · The Red Cup»</b> в этом же юните: новые буквы, звук → буква, слово ↔ картинка, сортировка /e/ и /u/, собери слово, впиши букву, история «верно / неверно», скороговорка вслух. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$::jsonb, 3)
  on conflict (lesson_id, sort_order) do update set type = excluded.type, payload = excluded.payload;
  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
  (v_hw, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/sam_phone.webp\" alt=\"\" style=\"height:auto;max-width:160px;float:right;margin:0 0 8px 12px\"><b>Агент, ключ пополнился!</b></p><p>Сегодня ты открыл пять новых символов: <b>c k e u r</b>. Потренируйся, пока не пришло новое сообщение от Агента X.</p>"}$blk$::jsonb, 0),
  (v_hw, 'flashcards', $blk${"title": "Новые буквы. Нажми на карточку — услышишь звук буквы.", "cards": [{"text": "c", "image": "https://classroom.wowteach.ru/media/reading10/u3/cat.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/c.mp3", "translation": "кошка (cat) · звук /k/"}, {"text": "k", "image": "https://classroom.wowteach.ru/media/reading10/u3/kid.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/k.mp3", "translation": "малыш (kid) · звук /k/"}, {"text": "e", "image": "https://classroom.wowteach.ru/media/reading10/u3/egg.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/e.mp3", "translation": "яйцо (egg) · звук /e/"}, {"text": "u", "image": "https://classroom.wowteach.ru/media/reading10/u3/umbrella.webp", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/u.mp3", "translation": "зонт (umbrella) · звук /ʌ/"}, {"text": "r", "image": "https://classroom.wowteach.ru/media/reading10/cipher/r.svg", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/r.mp3", "translation": "ракета (rocket) · звук /r/"}]}$blk$::jsonb, 1),
  (v_hw, 'quiz', $blk${"title": "Послушай звук и выбери букву.", "questions": [{"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/e.mp3", "correct": [0], "options": [{"text": "e"}, {"text": "a"}, {"text": "i"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/u.mp3", "correct": [1], "options": [{"text": "o"}, {"text": "u"}, {"text": "a"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/r.mp3", "correct": [2], "options": [{"text": "n"}, {"text": "m"}, {"text": "r"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/c.mp3", "correct": [0], "options": [{"text": "c"}, {"text": "d"}, {"text": "g"}]}, {"q": "", "type": "single", "audio": "https://vtcxghsqymwkyiogpndf.supabase.co/storage/v1/object/public/classroom-media/reading10/zvuki/k.mp3", "correct": [1], "options": [{"text": "t"}, {"text": "k"}, {"text": "p"}]}]}$blk$::jsonb, 2),
  (v_hw, 'match', $blk${"title": "Прочитай слово и найди его картинку.", "pairs": [{"left": "cat", "right": "картинка cat", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/cat.webp"}, {"left": "sun", "right": "картинка sun", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/sun.webp"}, {"left": "pen", "right": "картинка pen", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/pen.webp"}, {"left": "cup", "right": "картинка cup", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/cup.webp"}, {"left": "red", "right": "картинка red", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/red_paint.webp"}, {"left": "kid", "right": "картинка kid", "right_image": "https://classroom.wowteach.ru/media/reading10/u3/kid.webp"}]}$blk$::jsonb, 3),
  (v_hw, 'sort', $blk${"title": "Прочитай слова и распредели их: в каком слове звук /e/, а в каком — звук /u/?", "groups": [{"name": "e", "items": [{"text": "pen"}, {"text": "ten"}, {"text": "red"}, {"text": "net"}]}, {"name": "u", "items": [{"text": "sun"}, {"text": "cup"}, {"text": "run"}, {"text": "mug"}]}]}$blk$::jsonb, 4),
  (v_hw, 'order', $blk${"title": "Посмотри на картинку и собери слово из букв.", "items": [{"words": ["c", "a", "t"], "sentence": "cat", "image": "https://classroom.wowteach.ru/media/reading10/u3/cat.webp"}, {"words": ["s", "u", "n"], "sentence": "sun", "image": "https://classroom.wowteach.ru/media/reading10/u3/sun.webp"}, {"words": ["r", "e", "d"], "sentence": "red", "image": "https://classroom.wowteach.ru/media/reading10/u3/red_paint.webp"}, {"words": ["k", "i", "d"], "sentence": "kid", "image": "https://classroom.wowteach.ru/media/reading10/u3/kid.webp"}]}$blk$::jsonb, 5),
  (v_hw, 'gaps', $blk${"title": "Послушай слово и впиши пропущенную букву.", "mode": "type", "text": "p__e__n\nc__u__p\nr__e__d\ns__u__n\nk__i__t", "line_audio": ["", "", "", "", ""], "line_audio_tts": [{"text": "pen.", "voice": "en_GB-alba"}, {"text": "cup.", "voice": "en_GB-alba"}, {"text": "red.", "voice": "en_GB-alba"}, {"text": "sun.", "voice": "en_GB-alba"}, {"text": "kit.", "voice": "en_GB-alba"}], "line_image": ["https://classroom.wowteach.ru/media/reading10/u3/pen.webp", "https://classroom.wowteach.ru/media/reading10/u3/cup.webp", "https://classroom.wowteach.ru/media/reading10/u3/red_paint.webp", "https://classroom.wowteach.ru/media/reading10/u3/sun.webp", "https://classroom.wowteach.ru/media/reading10/u3/kit.webp"]}$blk$::jsonb, 6),
  (v_hw, 'quiz', $blk${"title": "Прочитай историю и ответь: верно или неверно?", "material": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/scene_cup.webp\" alt=\"\" style=\"height:auto;max-width:100%;border-radius:12px\"></p><p style=\"font-size:1.25em;line-height:1.6\">“Run! Get the red cup!” said Sam.<br>The red cup sits on a mat.<br>Dan gets it. In the cup — a map!<br>Sam and Dan run.</p>", "questions": [{"q": "The cup is red.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "The cup sits on a pen.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "In the cup — a map.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}]}$blk$::jsonb, 7),
  (v_hw, 'speaking', $blk${"title": "Прочитай вслух скороговорку и запиши себя 🎤", "html": "<p style=\"font-size:1.3em;line-height:1.6\">Run, run, run in the sun!<br>Get a cup, get a nut!<br>A red cat, a red pen,<br>Ten red cups — run, run, run!</p>", "sample": "", "sample_tts": {"text": "Run, run, run in the sun! Get a cup, get a nut! A red cat, a red pen, Ten red cups — run, run, run!", "voice": "en_GB-alba"}, "needs_review": true}$blk$::jsonb, 8),
  (v_hw, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/reading10/u3/dan_wave.webp\" alt=\"\" style=\"height:auto;max-width:140px;float:right;margin:0 0 8px 12px\"><b>Миссия выполнена!</b></p><p>Новое сообщение Агента X придёт на следующем уроке. До встречи, агент!</p>"}$blk$::jsonb, 9)
  on conflict (lesson_id, sort_order) do update set type = excluded.type, payload = excluded.payload;
end $$;
